window.MOTIF_CATALOG_CHUNKS[82]={"cards":[{"id":"MEJE-KW-005995","row_version":1,"title":"정체를 감춘 비밀 조직","original":"Covert Group","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"집단의 존재나 활동이 외부에 널리 알려지지 않도록 숨긴다. 비밀 유지 자체가 조직의 힘과 갈등의 조건이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005995/index.html"},{"id":"MEJE-KW-005996","row_version":1,"title":"평범한 간판 뒤의 비밀 조직","original":"Covert Group with Mundane Front","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"일상적인 업체나 모임으로 보이는 조직이 실제로는 별도의 비밀 임무를 수행한다. 겉모습과 활동의 간극이 정체 공개의 단서가 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005996/index.html"},{"id":"MEJE-KW-005997","row_version":1,"title":"얌전해 보이지만 짓궂은 상상을 하는 인물","original":"Covert Pervert","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"순진하거나 수줍게 보이던 인물이 뜻밖에 성적인 농담이나 암시를 알아듣고 말한다. 겉으로 보이는 이미지와 실제 생각의 차이에서 반전을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005997/index.html"},{"id":"MEJE-KW-005998","row_version":2,"title":"은폐를 위한 대역 복제체","original":"Cover-Up Clone","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"사라지거나 죽은 사람의 자리를 복제체로 채워 부재나 사건을 감춘다. 주변 인물이 미묘한 차이를 알아차리면서 은폐가 흔들린다. 복제체를 감춘 배후가 일상적인 조직으로 위장했다면 평범한 간판 뒤의 비밀 조직과 이어진다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-005998/index.html"},{"id":"MEJE-KW-005999","row_version":1,"title":"숨길 구매품을 다른 물건으로 가리기","original":"Cover-up Purchase","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사기 민망하거나 숨기고 싶은 물건을 사면서 평범한 물건도 함께 골라 구매 의도를 감추려는 장면.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005999/index.html"},{"id":"MEJE-KW-006000","row_version":1,"title":"커버 버전","original":"Cover Version","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"기존 곡을 다른 가수나 연주자가 새롭게 해석해 발표한 음악. 편곡과 목소리의 변화로 원곡과 다른 인상을 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006000/index.html"},{"id":"MEJE-KW-006001","row_version":2,"title":"겁쟁이라고 공개적으로 질책하기","original":"Cowardice Callout","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"두려워 물러선 인물에게 다른 사람이 용기가 없다고 직설적으로 비난한다. 비난이 행동 변화를 재촉하거나 관계의 갈등을 키운다. 비난받은 인물이 두려움을 안고도 행동할 때 겁이 많지만 용기를 내는 인물의 전환점이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006001/index.html"},{"id":"MEJE-KW-006002","row_version":3,"title":"맞서다 도망치는 게임 보스","original":"Cowardly Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 보스가 전투 중 피해를 받으면 달아나고 플레이어가 다시 찾아 싸워야 하는 전투 구조. 일정 구간에서는 직접 맞서므로 계속 도망만 다니는 적과 구분된다. 위험 앞에 먼저 달아나는 우두머리에게는 겁 많은 악역 부하들이 뒤따르기 쉽다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006002/index.html"},{"id":"MEJE-KW-006003","row_version":2,"title":"겁이 많지만 용기를 내는 인물","original":"Cowardly Lion","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소에는 겁을 내고 뒤로 물러서지만 중요한 순간에 친구나 목표를 위해 행동한다. 용기는 두려움이 없는 상태가 아니라 이를 넘는 선택으로 표현된다. 동행자의 겁 많은 모습은 겁 많은 동행자과도 맞닿지만 결정적 순간의 행동이 인물상을 가른다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006003/index.html"},{"id":"MEJE-KW-006004","row_version":1,"title":"겁 많은 악역 부하들","original":"Cowardly Mooks","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"수적으로는 위협적이지만 상대가 반격하면 쉽게 달아나는 악역의 부하 집단. 위세와 실제 전투 의지의 차이로 긴장을 누그러뜨린다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006004/index.html"},{"id":"MEJE-KW-006005","row_version":2,"title":"겁 많은 동행자","original":"Cowardly Sidekick","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"주인공과 함께 다니지만 위험을 만나면 먼저 겁을 내는 조력자. 긴장감을 말로 드러내거나 다른 인물의 대담함을 돋보이게 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006005/index.html"},{"id":"MEJE-KW-006006","row_version":1,"title":"노란색으로 표시한 비겁함","original":"Cowardly Yellow","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"노란색을 두려움이나 비겁함을 암시하는 시각적 신호로 사용한다. 색의 의미는 작품과 문화적 맥락에 따라 달라진다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006006/index.html"},{"id":"MEJE-KW-006007","row_version":3,"title":"카우보이","original":"Cowboy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"미국 서부의 목축 노동자에서 비롯된 인물형으로, 서부극에서는 말·모자·광활한 이동 공간과 결합해 독립적인 삶의 상징으로 그려진다. 역사적 직업과 장르적 이미지의 차이를 구분한다. 서부극의 인물 이미지는 다른 장르에 삽입된 카우보이풍 에피소드에서 새로운 역할을 얻는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006007/index.html"},{"id":"MEJE-KW-006008","row_version":2,"title":"다른 작품을 엉터리로 인용하기","original":"Cowboy BeBop at His Computer","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이나 보도가 다른 작품의 인물·설정·사실을 뻔히 틀리게 소개한다. 원작을 아는 관객에게는 확인 부족이 곧 드러나는 매체 제작 관습이다. 디지털 작업자의 결투식 구도는 카우보이의 장르적 이미지를 빌린다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006008/index.html"},{"id":"MEJE-KW-006009","row_version":1,"title":"규정을 무시하는 형사","original":"Cowboy Cop","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사건 해결을 위해 상관의 지시나 수사 절차를 자주 거스르는 경찰 인물상. 성과와 절차 위반 사이의 갈등이 이야기를 이끈다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006009/index.html"},{"id":"MEJE-KW-006010","row_version":2,"title":"카우보이풍 에피소드","original":"Cowboy Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"본래 다른 장르의 이야기에서 한 회차만 서부극의 배경·복장·결투 문법을 빌린다. 익숙한 인물을 낯선 장르 관습 속에 놓는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006010/index.html"},{"id":"MEJE-KW-006011","row_version":2,"title":"선악 편을 나누는 어린이 놀이","original":"Cowboys and Indians","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"아이들이 서부극이나 경찰과 도둑처럼 친숙한 대립 구도를 빌려 두 편으로 나누어 노는 역할놀이. 특정 역사 집단의 이름을 빌릴 때 고정관념이 끼어들 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006011/index.html"},{"id":"MEJE-KW-006012","row_version":2,"title":"보호자 뒤로 숨는 인물","original":"Cower Power","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"위험 앞에서 움츠린 인물이 가까운 동료나 보호자 뒤로 몸을 숨긴다. 두 인물 사이의 두려움과 보호 관계를 한 장면으로 보여준다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006012/index.html"},{"id":"MEJE-KW-006013","row_version":1,"title":"소 넘어뜨리기 소동","original":"Cow Tipping","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"시골의 밤놀이로 소를 넘어뜨린다는 이야기를 인물이 실행하거나 계획하는 장면. 현실의 보편적 관행이라기보다 허구 속 농촌 소동의 이미지로 다룬다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006013/index.html"},{"id":"MEJE-KW-006014","row_version":1,"title":"정체를 알 수 없는 도구들","original":"Cow Tools","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"용도와 작동 방식이 설명되지 않는 기묘한 도구들이 화면에 놓인다. 설명의 빈자리가 관객의 해석과 엉뚱한 상상을 부른다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006014/index.html"},{"id":"MEJE-KW-006015","row_version":1,"title":"수줍은 구애 자세","original":"Coy, Girlish Flirt Pose","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"몸을 작게 모으거나 손짓을 조심스럽게 하여 호감과 머뭇거림을 시각적으로 드러낸다. 자세는 인물의 감정을 빠르게 전달하는 연출이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006015/index.html"},{"id":"MEJE-KW-006016","row_version":3,"title":"아늑한 추리물","original":"Cozy Mystery","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"작은 공동체와 일상적인 공간을 배경으로 사건의 충격보다 인물 관계와 수수께끼 풀이에 무게를 두는 추리 장르. 독자가 다시 돌아오고 싶은 분위기가 핵심이다. 작은 동네를 배경으로 한 추리에서는 까다로운 이웃과의 일상적 갈등도 사건의 단서가 된다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-006016/index.html"},{"id":"MEJE-KW-006017","row_version":1,"title":"참사를 태연하게 들려주는 목소리","original":"Cozy Voice for Catastrophes","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"큰 재난이나 잔혹한 사건을 서술자가 평온하고 친근한 어조로 전달한다. 말투와 사건의 간극이 섬뜩함이나 풍자를 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006017/index.html"},{"id":"MEJE-KW-006018","row_version":1,"title":"깔끔하게 끝나는 화면 속 심폐소생술","original":"CPR: Clean, Pretty, Reliable","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품에서 심폐소생술을 짧고 간단하며 곧바로 회복되는 장면처럼 그리는 관습. 긴박한 구조 장면을 압축하는 매체 표현으로 다룬다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006018/index.html"},{"id":"MEJE-KW-006019","row_version":1,"title":"뜻밖의 허무한 패배","original":"Crack Defeat","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"실력상 우세해 보이는 경쟁자가 예상치 못한 사정으로 열세의 상대에게 진다. 실력과 결과의 어긋남이 웃음이나 충격을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006019/index.html"},{"id":"MEJE-KW-006020","row_version":3,"title":"황당함을 즐기는 팬 창작","original":"Crack Fic","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"설정이나 인물의 개연성을 일부러 과장하고 엉뚱한 조합을 밀어붙이는 팬 창작물. 진지한 원작을 놀이의 재료로 다시 쓴다. 개연성을 일부러 흔드는 팬 창작은 의외의 인물 조합 팬 커플링을 인물 관계의 소재로 삼기도 한다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-006020/index.html"},{"id":"MEJE-KW-006021","row_version":1,"title":"하늘에 금이 가다","original":"Crack in the Sky","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"하늘이 물체처럼 갈라지는 모습을 보여 세계의 질서나 현실 자체가 흔들리고 있음을 알린다. 거대한 변화를 한눈에 보이게 하는 이미지다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006021/index.html"},{"id":"MEJE-KW-006022","row_version":1,"title":"취미가 생활비를 압도하다","original":"Crack Is Cheaper","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"수집이나 취미에 필요한 물품값이 예상보다 훨씬 커져 인물이 비용에 놀란다. 좋아하는 일에 쏟는 열정과 현실의 지출을 대비한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-006022/index.html"},{"id":"MEJE-KW-006023","row_version":1,"title":"등이 삐끗하는 순간","original":"*Crack!* \"Oh, My Back!\"","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"몸을 움직인 직후 등에서 소리가 나고 인물이 갑자기 통증을 호소한다. 신체의 취약함을 짧은 몸짓과 소리로 웃음거리로 만드는 연출이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006023/index.html"},{"id":"MEJE-KW-006024","row_version":1,"title":"의외의 인물 조합 팬 커플링","original":"Crack Pairing","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"원작에서 연인으로 이어질 가능성이 낮은 두 인물을 팬이 한 쌍으로 상상한다. 관계의 개연성보다 낯선 조합이 주는 재미를 탐색한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-006024/index.html"},{"id":"MEJE-KW-006025","row_version":1,"title":"차가운 태도의 작은 균열","original":"Cracks in the Icy Façade","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"늘 냉담하던 인물이 잠깐 다정함이나 약한 마음을 드러낸다. 짧은 변화가 겉모습 뒤의 성격을 암시한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006025/index.html"},{"id":"MEJE-KW-006026","row_version":2,"title":"남겨진 물건을 품에 안기","original":"Cradle of Loneliness","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"잃어버린 사람이나 관계를 떠올리게 하는 물건을 가슴에 안는다. 말없이 드러나는 상실감과 그리움이 장면의 중심이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006026/index.html"},{"id":"MEJE-KW-006027","row_version":1,"title":"요람부터 무덤까지의 인물 서사","original":"Cradle-to-Grave Character","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"한 인물의 탄생이나 유년기부터 노년 또는 죽음까지 긴 생애를 따라간다. 각 시기의 변화가 하나의 삶의 궤적을 이룬다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006027/index.html"},{"id":"MEJE-KW-006028","row_version":2,"title":"죽인 상대를 품에 안다","original":"Cradling Your Kill","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 자신이 죽인 사람을 안고 복잡한 감정을 드러낸다. 행위 뒤의 죄책감·집착·상실을 대사 없이 보여주는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006028/index.html"},{"id":"MEJE-KW-006029","row_version":2,"title":"동물에서 얻은 장비","original":"Crafted from Animals","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"가상의 생물이나 동물의 일부가 무기·방어구·장신구의 재료가 된다. 그 생물의 특성이 장비의 외형이나 상징성으로 이어진다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006029/index.html"},{"id":"MEJE-KW-006030","row_version":2,"title":"장인의 신","original":"Craftsman God","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"제작·대장간·공예를 관장하는 신격이 등장한다. 창작과 기술의 권위를 신화적 존재에 부여한다. 제작의 권능이 살아 있는 존재에까지 미치면 생명 창조의 신화적 주체가 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006030/index.html"},{"id":"MEJE-KW-006031","row_version":1,"title":"관 속에 다른 시신을 숨기다","original":"Cramming the Coffin","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이미 장례를 앞둔 관에 별도의 시신이 들어가면서 죽음의 진상이나 범죄가 가려진다. 장례라는 공적 절차가 비밀을 숨기는 이야기 장치가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006031/index.html"},{"id":"MEJE-KW-006032","row_version":1,"title":"입시 학원","original":"Cram School","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"시험과 진학을 목표로 정규 학교 밖에서 집중적으로 공부하는 교육 기관. 경쟁·압박·동료 관계가 이야기에 모인다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006032/index.html"},{"id":"MEJE-KW-006033","row_version":1,"title":"만화식 머리 혹","original":"Cranial Eruption","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"머리에 충격을 받은 인물에게 크고 둥근 혹이 곧바로 솟아오른 것처럼 그린다. 실제 상처보다 만화적 반응을 앞세운 시각 약속이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006033/index.html"},{"id":"MEJE-KW-006034","row_version":1,"title":"머릿속 금속판의 뜻밖의 기능","original":"Cranial Plate Ability","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물의 머리에 있는 의료용 금속판이 기이한 능력이나 위기 탈출의 이유로 쓰인다. 현실 의료기기와는 다른 허구적 기능이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006034/index.html"},{"id":"MEJE-KW-006035","row_version":3,"title":"머리에 든 로봇의 두뇌","original":"Cranial Processing Unit","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인간형 로봇의 사고를 담당하는 장치가 사람처럼 머리 안에 놓인다. 인간 신체의 구성을 기계 존재에게 옮긴 설정이다. 로봇의 머리를 사고 장치로 보는 설정은 이를 물건을 담는 머리 안의 수납공간으로 바꾸는 표현과 대비된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006035/index.html"},{"id":"MEJE-KW-006036","row_version":1,"title":"몸과 떨어진 머리를 되찾다","original":"Cranium Chase","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"분리되어도 살아 있는 머리와 몸이 서로를 찾아 움직인다. 몸의 경계가 뒤틀린 상황을 추적극이나 희극으로 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006036/index.html"},{"id":"MEJE-KW-006037","row_version":1,"title":"머리 안의 수납공간","original":"Cranium Compartment","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물의 머리가 열려 작은 물건을 넣거나 꺼낼 수 있는 공간으로 그려진다. 신체를 기이한 소도구처럼 다루는 만화적 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006037/index.html"},{"id":"MEJE-KW-006038","row_version":1,"title":"머리 위에 올라타 이동하기","original":"Cranium Ride","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 다른 존재의 머리 위에 올라타 장애물을 넘거나 길을 건넌다. 적이나 동료의 몸이 이동 경로의 일부가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006038/index.html"},{"id":"MEJE-KW-006039","row_version":2,"title":"심술궂게 그린 게","original":"Cranky Crabs","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"게가 늘 불만스럽고 성난 듯 반응하는 캐릭터로 표현된다. 동물의 외형과 움직임에 인간적 성격을 덧씌우는 방식이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006039/index.html"},{"id":"MEJE-KW-006040","row_version":2,"title":"까다로운 집주인","original":"Cranky Landlord","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"거주자를 사사건건 감시하고 불평하는 집주인 인물상. 사소한 생활 갈등을 반복적으로 일으키는 이웃 관계의 축이다. 거주 공간에서 반복되는 마찰은 까다로운 이웃이라는 더 넓은 인물상과 연결된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006040/index.html"},{"id":"MEJE-KW-006041","row_version":1,"title":"까다로운 이웃","original":"Cranky Neighbor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인접해 살며 소음이나 생활 습관을 문제 삼아 잦은 다툼을 만드는 인물. 가까운 거리 때문에 갈등을 쉽게 피할 수 없다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006041/index.html"},{"id":"MEJE-KW-006042","row_version":2,"title":"믿을 수 없는 허술한 기술","original":"Crapola Tech","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"제대로 작동할 듯 보이지만 중요한 순간마다 고장 나거나 엉뚱한 결과를 내는 기술이나 발명품. 기대와 성능의 차이가 사건을 만든다. 낡은 놀이 시설의 오작동을 앞세우면 허술한 유원지의 불안을 기술적 결함으로 구체화한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006042/index.html"},{"id":"MEJE-KW-006043","row_version":2,"title":"허술한 유원지","original":"Crappy Carnival","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"낡고 관리가 부실한 놀이공원이 화려한 즐거움 대신 불안과 실망을 준다. 위험해 보이는 시설이 희극이나 위기의 배경이 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006043/index.html"},{"id":"MEJE-KW-006044","row_version":1,"title":"엉망이 된 명절","original":"Crappy Holidays","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"즐거워야 할 명절이나 기념일에 다툼과 사고가 겹쳐 기대가 무너진다. 특별한 날이라는 약속이 실패를 더 크게 보이게 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006044/index.html"},{"id":"MEJE-KW-006045","row_version":1,"title":"어설픈 손수 만든 선물","original":"Crappy Homemade Gift","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"정성을 들여 만들었지만 완성도가 낮아 받는 사람이 당황하는 선물. 마음과 결과물 사이의 간극이 관계의 반응을 이끈다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006045/index.html"},{"id":"MEJE-KW-006046","row_version":3,"title":"달콤한 겉모습 아래의 암울한 세계","original":"Crapsaccharine World","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"밝고 귀여운 외형을 내세우지만 안쪽에는 착취나 잔혹함이 숨은 세계. 겉모습과 실제 질서의 차이가 발견될수록 불안이 커진다. 밝은 포장 아래의 실제 질서는 암울한 세계과 닮았지만 발견의 대비가 핵심이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006046/index.html"},{"id":"MEJE-KW-006047","row_version":2,"title":"비교 때문에 암울해 보이는 세계","original":"Crapsack Only by Comparison","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"다른 더 나은 세계와 나란히 놓으면 비참해 보이지만 그 자체로는 살 만한 세계. 평가 기준이 바뀌면 같은 배경의 인상도 달라진다. 평가 기준이 달라지면 같은 배경이 암울한 세계으로 오해되기도 한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006047/index.html"},{"id":"MEJE-KW-006048","row_version":1,"title":"암울한 세계","original":"Crapsack World","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"폭력·불평등·절망이 일상에 깊게 스며들어 살아가기 어려운 허구 세계. 인물의 선택과 작은 희망이 이 환경에 맞서 드러난다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006048/index.html"},{"id":"MEJE-KW-006049","row_version":2,"title":"가혹한 현실을 피해 들어가는 환상","original":"Crapsack World, Escapist Sanctuary","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"세계 전체가 가혹해 인물이 꿈, 환상, 가상현실 같은 비현실적 경험을 피난처로 삼는다. 도피가 삶을 버티는 방식이 되면서 현실과의 갈등을 낳는다. 안전한 장소의 바깥을 채우는 환경은 암울한 세계이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006049/index.html"},{"id":"MEJE-KW-006050","row_version":1,"title":"급하게 배우며 착륙하기","original":"Crash Course Landing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"해당 비행기를 착륙시켜 본 적 없는 인물이 위기 속에서 다른 사람의 안내를 받아 착륙해야 한다. 짧은 시간에 배운 역할을 즉시 수행하는 극적 상황이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006050/index.html"},{"id":"MEJE-KW-006051","row_version":1,"title":"현실 소리에 무너지는 꿈","original":"Crashing Dreams","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"잠든 인물의 주변에서 들리는 소리나 감각이 꿈의 사건으로 스며들다가 각성을 부른다. 꿈과 현실의 경계를 뒤늦게 드러내는 장치다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006051/index.html"},{"id":"MEJE-KW-006052","row_version":1,"title":"대관식에 난입하다","original":"Crashing the Coronation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"왕위 계승이나 즉위의 정당성을 다투는 인물이 대관식에 끼어들어 의식을 중단시킨다. 공개된 자리에서 권력의 합법성이 시험대에 오른다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006052/index.html"},{"id":"MEJE-KW-006053","row_version":1,"title":"추격 중 여성들의 사적 공간에 난입하기","original":"Crashing Through the Harem","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"도망치거나 쫓는 인물이 여성들이 목욕하거나 옷을 갈아입는 공간을 갑자기 가로질러 소동을 만든다. 민망함을 웃음거리로 삼지만 사생활 침해의 맥락도 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006053/index.html"},{"id":"MEJE-KW-006054","row_version":1,"title":"천장을 뚫고 나타나다","original":"Crash in Through the Ceiling","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 위쪽 구조물을 뚫고 떨어지며 장면에 갑자기 등장한다. 예상 밖의 진입 방향이 충격이나 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006054/index.html"},{"id":"MEJE-KW-006055","row_version":1,"title":"부딪치며 시작한 첫 만남","original":"Crash-Into Hello","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"두 인물이 걷거나 달리다 충돌하면서 처음 만난다. 우연한 신체 접촉이 대화와 관계의 출발점이 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006055/index.html"},{"id":"MEJE-KW-006056","row_version":1,"title":"경제 붕괴를 부르는 행동","original":"Crash the Economy","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물의 음모나 실수가 경제 질서를 흔들어 사회 전체의 생활과 제도에 위기를 낳는 전개.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006056/index.html"},{"id":"MEJE-KW-006057","row_version":2,"title":"무례하게 그려진 캐나다인","original":"Crass Canuck","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"예의 바르다는 통념과 반대로 캐나다인 인물이 퉁명스럽거나 공격적으로 행동한다. 국민성에 관한 고정관념을 뒤집는 캐릭터 표현이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006057/index.html"},{"id":"MEJE-KW-006058","row_version":1,"title":"상자로 가득한 게임 공간","original":"Crate Expectations","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 배경 곳곳에 같은 나무 상자가 반복 배치된다. 상자는 엄폐물·장애물·보급품처럼 공간을 읽는 표지가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006058/index.html"},{"id":"MEJE-KW-006059","row_version":1,"title":"충격으로 남는 거대한 구덩이","original":"Crater Power","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"강한 힘이 발휘된 자리에 큰 분화구 같은 흔적이 남는다. 파괴의 규모를 통해 능력의 크기를 한눈에 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006059/index.html"},{"id":"MEJE-KW-006060","row_version":1,"title":"화면 아래로 흐르는 자막 띠","original":"Crawl","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"방송 화면 가장자리를 따라 짧은 정보가 연속해서 움직인다. 본화면과 별개의 소식이나 긴급성을 동시에 전달한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006060/index.html"},{"id":"MEJE-KW-006061","row_version":1,"title":"불안정함을 암시하는 동심원 눈","original":"Crazed Concentric Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 눈동자를 여러 겹의 동심원으로 그려 심리적 불안정이나 광기를 암시하는 허구의 시각 기호. 실제 정신 질환의 특징을 뜻하지는 않는다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006061/index.html"},{"id":"MEJE-KW-006062","row_version":2,"title":"고양이와 사는 괴짜 여성","original":"Crazy Cat Lady","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"많은 고양이와 지내는 여성을 외롭거나 별난 인물로 묘사하는 고정된 캐릭터 이미지. 실제 반려 생활과는 구별해 표현의 편견을 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006062/index.html"},{"id":"MEJE-KW-006063","row_version":1,"title":"기이한 식습관을 불안정함의 표지로 쓰기","original":"Crazy Consumption","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"특이한 먹는 방식이나 음식 선택을 정신적 불안정 또는 사회적 이질감의 표지로 그리는 관습. 식습관과 심리 상태를 단정적으로 연결하는 낙인성 표현으로 읽을 필요가 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006063/index.html"},{"id":"MEJE-KW-006064","row_version":1,"title":"서로 다른 문화의 관습 비교","original":"Crazy Cultural Comparison","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"다른 문화권 출신 인물들이 인사·식사·사회 규범을 나란히 비교한다. 익숙한 관습을 낯설게 바라보게 하는 대화 장면이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006064/index.html"},{"id":"MEJE-KW-006065","row_version":2,"title":"황당하지만 통하는 계획","original":"Crazy Enough to Work","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"상식으로는 성공하기 어려워 보이는 계획이 예상 밖의 사정 때문에 실제로 먹혀든다. 무모함과 결과의 간극이 쾌감이나 웃음을 준다. 터무니없어 보이는 계획도 모든 상황에 대비한 인물이 마련한 대비책에서 실마리를 얻을 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006065/index.html"},{"id":"MEJE-KW-006066","row_version":1,"title":"노숙인을 괴짜로 그리는 관습","original":"Crazy Homeless People","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"주거가 불안정한 인물을 곧바로 불안정하거나 위험한 사람으로 단순화해 표현한다. 삶의 조건과 정신 건강을 뒤섞는 고정관념으로 읽는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006066/index.html"},{"id":"MEJE-KW-006067","row_version":1,"title":"불안정한 사람은 열정적인 연인이라는 편견","original":"Crazy in the Head, Crazy in the Bed","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"정서적으로 불안정하게 그려진 인물이 성적으로 더 매력적일 것이라는 통념을 관계 묘사에 사용한다. 정신 건강을 매력이나 위험성으로 환원하는 고정관념이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006067/index.html"},{"id":"MEJE-KW-006068","row_version":1,"title":"엉뚱해서 멋진 인물","original":"Crazy Is Cool","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사회적 기대를 거스르는 기발한 언행이 인물의 매력으로 받아들여진다. 여기서의 엉뚱함은 임상적 정신 질환과 별개의 성격 표현이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006068/index.html"},{"id":"MEJE-KW-006069","row_version":1,"title":"통제하려 드는 질투 많은 남자","original":"Crazy Jealous Guy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"연인의 관심이 다른 사람에게 향하는 것을 위협으로 받아들여 과하게 간섭하는 남성 인물상. 질투가 통제와 폭력으로 번질 때 관계의 위험을 드러낸다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006069/index.html"},{"id":"MEJE-KW-006070","row_version":1,"title":"믿기 어려운 기묘한 회상","original":"Crazy Memory","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 과거를 회상하며 너무 황당해서 사실인지 의심스러운 이야기를 꺼낸다. 허풍·착각·진실 중 어느 쪽인지가 장면의 재미가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006070/index.html"},{"id":"MEJE-KW-006071","row_version":1,"title":"체스 천재를 괴짜로 그리기","original":"Crazy People Play Chess","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"뛰어난 체스 선수를 기이한 행동이나 집착을 지닌 인물로 묘사한다. 높은 지능과 불안정한 성격을 자동으로 묶는 표현 관습이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006071/index.html"},{"id":"MEJE-KW-006072","row_version":2,"title":"모든 상황에 대비한 인물","original":"Crazy-Prepared","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"가능성 낮은 위기까지 예상하고 필요한 물품과 대안을 갖춘 인물. 예측이 적중할 때는 유능해 보이고 지나칠 때는 희극이 된다. 늘 대비하는 태도가 위협에 대한 강한 확신과 결합하면 과도하게 대비하는 생존주의자의 인물상에 가까워진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006072/index.html"},{"id":"MEJE-KW-006073","row_version":2,"title":"기이한 태도로 버티는 정신","original":"Crazy Sane","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"견디기 어려운 세계에서 인물이 남들이 보기엔 엉뚱한 행동으로 일상을 버틴다. 행동의 기이함이 무너짐을 막는 개인적 적응으로 그려진다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006073/index.html"},{"id":"MEJE-KW-006074","row_version":1,"title":"과도하게 대비하는 생존주의자","original":"Crazy Survivalist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"다가올 재난이나 공격을 확신하고 늘 경계하며 준비하는 인물. 실제 위기가 닥치면 그의 대비가 과장인지 통찰인지 다시 평가된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006074/index.html"},{"id":"MEJE-KW-006075","row_version":1,"title":"별난 일이 끊이지 않는 직장","original":"Crazy Workplace","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"동료의 행동과 업무 사건이 매일 예측을 벗어나 직장 생활 자체가 소동이 된다. 평범한 근무 공간이 희극적 사건의 무대가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006075/index.html"},{"id":"MEJE-KW-006076","row_version":2,"title":"적이 만들어 낸 영웅","original":"Create Your Own Hero","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"악역의 행동이 이를 막으려는 영웅의 탄생이나 성장을 불러온다. 적대 관계가 한쪽의 존재 이유를 만든다는 인과를 드러낸다. 적대 관계의 인과를 반대로 뒤집으면 영웅이 만들어 낸 악당이라는 별도의 이야기 구조가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006076/index.html"},{"id":"MEJE-KW-006077","row_version":2,"title":"영웅이 만들어 낸 악당","original":"Create Your Own Villain","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"영웅의 실수나 선택이 누군가를 적으로 돌아서게 한다. 선한 의도도 타인에게 남긴 피해를 피할 수 없다는 갈등을 만든다. 영웅의 행동이 적을 만들듯 악역의 행동도 적이 만들어 낸 영웅으로 이어질 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006077/index.html"},{"id":"MEJE-KW-006079","row_version":2,"title":"생명 창조를 찬미하다","original":"Creating Life Is Awesome","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"새로운 생명을 만드는 일을 경이롭고 희망적인 성취로 바라본다. 창조의 결과가 두려움보다 돌봄과 가능성의 이야기로 이어진다. 창조를 경이로 보는 관점은 같은 행위를 금기로 읽는 생명 창조를 금기로 여기다과 대조된다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006079/index.html"},{"id":"MEJE-KW-006080","row_version":2,"title":"생명 창조를 금기로 여기다","original":"Creating Life Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"인간이나 다른 존재가 생명을 만드는 일을 오만하거나 위험한 금기 위반으로 그린다. 창조의 결과가 책임과 통제의 문제를 부각한다. 금기를 둘러싼 갈등은 실제 생명 창조이 일어났을 때 구체화된다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006080/index.html"},{"id":"MEJE-KW-006081","row_version":3,"title":"뜻밖에 태어난 생명","original":"Creating Life Is Unforeseen","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"다른 목적의 실험이나 작업 결과가 예기치 않게 자아를 가진 생명으로 나타난다. 창조자는 예상하지 못한 존재를 어떻게 대할지 선택해야 한다. 우연히 나타난 존재도 결국 생명 창조의 결과로서 창조자의 책임을 묻는다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006081/index.html"},{"id":"MEJE-KW-006082","row_version":2,"title":"창조와 파괴를 나란히 놓기","original":"Creation/Destruction Juxtaposition","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"무언가가 태어나는 과정과 사라지는 과정을 이야기 속에서 나란히 놓는다. 두 힘이 선악과 일대일로 대응하지 않는다는 생각도 드러낸다. 두 사건을 교차할 때 창조의 장면에는 생명 창조을 배치할 수 있다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006082/index.html"},{"id":"MEJE-KW-006083","row_version":3,"title":"창세 신화","original":"Creation Myth","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"세계·생명·인간 또는 신들이 어떻게 시작되었는지를 설명하는 신화적 이야기. 공동체의 세계 이해와 질서를 뒷받침하는 근원 서사다. 세계가 어떻게 시작되었는지 설명하는 이야기에는 장인의 신이 그 원인으로 등장할 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006083/index.html"},{"id":"MEJE-KW-006084","row_version":4,"title":"창조 과정 보여 주기","original":"Creation Sequence","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"물건이나 생명체가 만들어지는 과정을 단계별 장면으로 보여 준다. 완성품뿐 아니라 제작 과정 자체가 경이감과 기대를 만든다. 제작의 대상이 세계 전체이고 그 과정이 줄거리 안에서 벌어진다면 이야기 속 세계 창조으로 이어진다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006084/index.html"},{"id":"MEJE-KW-006085","row_version":2,"title":"이야기 속 세계 창조","original":"Creation Story","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"신이나 초월적 존재가 세계를 만드는 사건이 작품 안에서 실제로 벌어진다. 이야기의 시작, 중간, 끝 어디에서든 세계의 기원을 직접 보여 줄 수 있다. 세계의 생명체를 여러 초월자가 의논해 설계한다면 생명체를 설계하는 초월자 회의이 창조 장면에 더해진다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006085/index.html"},{"id":"MEJE-KW-006086","row_version":2,"title":"창의적인 엔딩 크레딧","original":"Creative Closing Credits","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"이름을 나열하는 엔딩 크레딧에 영상·음악·구성을 더해 그 자체를 볼거리로 만든다. 관객이 본편 이후에도 화면에 머물게 한다. 명단의 글자와 이름 자체로 웃음을 만들 때는 크레딧 안에 숨긴 농담이 크레딧의 한 요소가 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006086/index.html"},{"id":"MEJE-KW-006087","row_version":1,"title":"창작 방향 차이로 갈라서기","original":"Creative Differences","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"출연자나 제작자가 작품 또는 팀을 떠난 이유를 서로 다른 창작 방향으로 설명한다. 실제 의견 충돌일 수도 있고 공개적으로 갈등을 완곡하게 표현한 말일 수도 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006087/index.html"},{"id":"MEJE-KW-006088","row_version":1,"title":"창조력을 잃은 우월 종족","original":"Creative Sterility","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"강력하거나 진보한 존재가 인간보다 많은 능력을 가졌지만 새로운 것을 창조하는 힘은 잃었다고 그린다. 인간의 불완전함과 창조성을 대비시킨다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006088/index.html"},{"id":"MEJE-KW-006089","row_version":1,"title":"제작자가 팬 밈을 언급하기","original":"Creator-Acknowledged Meme","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"작품에서 유래한 팬들의 농담이나 유행어를 제작진이 작품 밖에서 알아보고 언급한다. 팬덤의 해석이 제작자와 만나는 접점이 된다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006089/index.html"},{"id":"MEJE-KW-006090","row_version":3,"title":"창작자가 자기 작품을 싫어하기","original":"Creator Backlash","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자가 과거에 만든 작품을 공개적으로 불편해하거나 후회한다. 관객의 사랑과 제작자의 평가가 어긋날 때 두 기억이 함께 남는다. 작품 전체보다 관객이 계속 요구하는 특정 인물이 부담이라면 창작자를 괴롭히는 인기 인물의 경우에 가깝다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006090/index.html"},{"id":"MEJE-KW-006091","row_version":2,"title":"창작자의 위기가 작품에 번지기","original":"Creator Breakdown","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자의 개인적 고통이 작품의 인물과 사건에 스며들어 분위기가 갑자기 어두워진다. 작품의 변화가 제작 시기의 삶과 연결되어 해석된다. 삶의 회복이 작품의 정서 변화로 나타나는 창작자의 회복이 작품에 번지기은 같은 제작자와 작품의 관계를 반대 방향에서 보여 준다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006091/index.html"},{"id":"MEJE-KW-006092","row_version":2,"title":"제작자의 깜짝 출연","original":"Creator Cameo","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품을 만든 사람이나 감독이 자기 작품 속에 잠깐 모습을 드러낸다. 알아보는 관객에게는 제작 과정의 흔적이 화면 안에서 발견된다. 창작자가 직접 등장하는 대신 자기 이전 작품의 흔적을 심으면 자기 다른 작품을 슬쩍 언급하기이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006092/index.html"},{"id":"MEJE-KW-006093","row_version":1,"title":"자기 직업을 놀리는 창작자","original":"Creator Career Self-Deprecation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자가 자신의 직업과 닮은 인물을 우스꽝스럽게 그려 업계의 버릇을 풍자한다. 내부 경험이 농담의 구체성을 높인다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006093/index.html"},{"id":"MEJE-KW-006094","row_version":1,"title":"창작자가 직접 고른 출연자","original":"Creator-Chosen Casting","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원작자나 제작자가 특정 배우·연기자를 역할에 직접 선택한다. 배역에 대한 창작자의 구상이 캐스팅에 뚜렷하게 반영된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006094/index.html"},{"id":"MEJE-KW-006095","row_version":1,"title":"함께 창작하는 연인","original":"Creator Couple","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연인이나 부부인 두 창작자가 서로의 작업에 실질적으로 기여한다. 사적인 관계와 공동 제작의 성과가 함께 주목받는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006095/index.html"}]}.cards;